// The line-art set: the guest's world in fine chalk-white lines on black, with amber or red only where there is
// light. It takes the place of the glossy 3D props and the lily, and stands in where a photograph would be wrong.
// Drawn the way a watchmaker or an architect draws: one viewpoint for the whole set (a near elevation, looking down
// about 12 degrees, through a long lens), true ellipses, real sizes, and the line broken wherever light catches an
// edge. The drawings were built in 3D and projected (so every ellipse is exact); here they are path data, not for
// editing by hand point by point. LineArt.astro draws one; styles/lineart.css sets its line, its light and its
// draw-in.
//
// Each drawing:
//   box     its viewBox, width and height in its own units; on the page it is as wide as its container
//   alt     what it shows, for a page that labels it (LineArt label=…); a drawing with no label is decoration
//   lines   by weight: contour (1.25 px), detail (0.75 px at 45 %), hint (reflections and construction, 0.5 px at
//           25 %). Each line is [path, length]: the length counted in its own longest stroke, which is how the
//           draw-in moves every stroke at the same pace and ends with the longest; a third item is a style of its
//           own (the smoke fades as it rises)
//   defs    the gradients, masks and filters of its light and shade; {id} becomes the drawing's own prefix, so two
//           of the same drawing on one page never share an id
//   shade   a soft black shadow on the floor, drawn first
//   light   what is lit (whisky, a pool, a seam), under the lines. Amber is fixed; red and the laser take the
//           site's light (--light, --light-core, --lasers: lineart.css). A drawing with the club's needle in it
//           groups its light (la-needle, then la-warm), so the draw-in lights the needle first, then the room
import type { L } from './i18n';

export type LineArtName = 'glass' | 'bottle' | 'cigar' | 'cloche' | 'cuff' | 'car' | 'chair' | 'shoulder' | 'door' | 'lamp' | 'card' | 'guest';
/** A line: its path, its length in its own longest stroke (for the draw-in), and a style of its own if it has one. */
export type Stroke = readonly [d: string, length: number, style?: string];
export interface Drawing {
  box: readonly [number, number];
  alt: L;
  lines: { contour: readonly Stroke[]; detail: readonly Stroke[]; hint: readonly Stroke[] };
  defs?: string;
  shade?: string;
  light?: string;
}

